/* global require, module */
/* eslint-disable @typescript-eslint/no-require-imports -- Expo loads this config plugin as CommonJS. */
const {
  withAndroidManifest,
  withDangerousMod,
} = require('@expo/config-plugins');
const fs = require('node:fs/promises');
const path = require('node:path');

// Maintained here because android/ is regenerated by Expo prebuild.
module.exports = function withPrivateData(config) {
  config = withAndroidManifest(config, (config) => {
    const application = config.modResults.manifest.application[0].$;
    application['android:allowBackup'] = 'false';
    application['android:fullBackupContent'] = '@xml/newpm_backup_rules';
    application['android:dataExtractionRules'] =
      '@xml/newpm_data_extraction_rules';
    return config;
  });
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const directory = path.join(
        config.modRequest.platformProjectRoot,
        'app/src/main/res/xml',
      );
      await fs.mkdir(directory, { recursive: true });
      const exclude = '    <exclude domain="file" path="newpm/" />';
      await fs.writeFile(
        path.join(directory, 'newpm_backup_rules.xml'),
        `<?xml version="1.0" encoding="utf-8"?>
<full-backup-content>
${exclude}
</full-backup-content>
`,
      );
      await fs.writeFile(
        path.join(directory, 'newpm_data_extraction_rules.xml'),
        `<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
  <cloud-backup>
${exclude}
  </cloud-backup>
  <device-transfer>
${exclude}
  </device-transfer>
</data-extraction-rules>
`,
      );
      return config;
    },
  ]);
};
